-- Adds a playful mix of conversation, show-and-tell, and light physical prompts.
-- English is canonical; localized copy is stored in the translations JSONB column.
-- Existing rows are updated with these translations and duplicate text is not created.
ALTER TABLE public.prompts
ADD COLUMN IF NOT EXISTS translations JSONB NOT NULL DEFAULT '{}'::JSONB;

INSERT INTO public.prompts (id, text, translations, "createdAt")
SELECT
  gen_random_uuid()::text,
  prompt_text,
  jsonb_build_object('tr', prompt_tr),
  NOW()
FROM (VALUES
  ('Give us a dramatic weather report for wherever you are right now.', 'Şu an bulunduğun yer için dramatik bir hava durumu sunumu yap.'),
  ('What tiny inconvenience would you ban forever?', 'Hangi küçük rahatsızlığı sonsuza dek yasaklardın?'),
  ('Show us the most random object within arm''s reach.', 'Elinin altında bulunan en alakasız nesneyi göster.'),
  ('What is your most controversial food opinion?', 'Yemeklerle ilgili en tartışmalı fikrin ne?'),
  ('Describe your day so far using only three words.', 'Bugününü şimdiye kadar sadece üç kelimeyle anlat.'),
  ('What song would play during your entrance today?', 'Bugün bir yere girerken arkada hangi şarkı çalardı?'),
  ('Show us something you own that has a surprisingly good story.', 'Şaşırtıcı derecede güzel bir hikâyesi olan bir eşyanı göster.'),
  ('If your mood were a snack, what snack would it be?', 'Ruh hâlin bir atıştırmalık olsaydı ne olurdu?'),
  ('What is a useless skill you are weirdly proud of?', 'Garip bir şekilde gurur duyduğun işe yaramaz yeteneğin ne?'),
  ('Give an everyday object near you a luxury commercial.', 'Yakınındaki sıradan bir nesne için lüks bir reklam çek.'),
  ('What fictional world would you visit for exactly one day?', 'Hangi kurgusal dünyayı tam bir günlüğüne ziyaret ederdin?'),
  ('Show us the last thing that made you smile.', 'Seni en son gülümseten şeyi göster.'),
  ('What is a small hill you are willing to die on?', 'Sonuna kadar savunacağın küçük ama önemli fikrin ne?'),
  ('Pitch your current favorite show in ten seconds.', 'Şu anki favori dizini on saniyede bize satmaya çalış.'),
  ('What would your warning label say?', 'Senin uyarı etiketinde ne yazardı?'),
  ('Show us today''s outfit and give it a ridiculous name.', 'Bugünkü kombinini göster ve ona saçma bir isim ver.'),
  ('What is the strangest compliment you have ever received?', 'Şimdiye kadar aldığın en garip iltifat neydi?'),
  ('If today had a title, what would it be?', 'Bugünün bir başlığı olsaydı ne olurdu?'),
  ('Show us the best view you can reach in one minute.', 'Bir dakika içinde ulaşabileceğin en güzel manzarayı göster.'),
  ('What is something everyone seems to love except you?', 'Senin dışında herkesin sevdiği şey ne?'),
  ('Invent a new holiday. What are we celebrating?', 'Yeni bir bayram icat et. Neyi kutluyoruz?'),
  ('Show us the oldest thing you are carrying today.', 'Bugün yanında taşıdığın en eski şeyi göster.'),
  ('What is your go-to excuse when you want to leave early?', 'Erken ayrılmak istediğinde kullandığın klasik bahanen ne?'),
  ('Which emoji best describes your week? Recreate it with your face.', 'Bu haftanı en iyi hangi emoji anlatıyor? Yüzünle canlandır.'),
  ('What is a childhood snack you would still defend today?', 'Çocukluğundan bugün bile savunacağın atıştırmalık hangisi?'),
  ('Give us a ten-second tour of the most interesting corner near you.', 'Yakınındaki en ilginç köşeyi on saniyede gezdir.'),
  ('If you could instantly master one oddly specific skill, what would it be?', 'Çok özel bir beceride anında ustalaşabilseydin bu ne olurdu?'),
  ('What is the funniest thing you believed as a child?', 'Çocukken inandığın en komik şey neydi?'),
  ('Show us what is currently in your pocket or bag.', 'Şu an cebinde veya çantanda ne olduğunu göster.'),
  ('What ordinary thing makes you feel surprisingly fancy?', 'Hangi sıradan şey kendini beklenmedik şekilde havalı hissettiriyor?'),
  ('Name one thing you would be unbeatable at in a very boring Olympics.', 'Çok sıkıcı bir olimpiyatta yenilmez olacağın bir dal söyle.'),
  ('What is your current hyperfixation? Give us the quick version.', 'Şu sıralar neye fena hâlde taktın? Kısaca anlat.'),
  ('Show us your drink and review it like a professional critic.', 'İçeceğini göster ve profesyonel bir eleştirmen gibi yorumla.'),
  ('What is a purchase under $20 that improved your life?', 'Hayatını iyileştiren uygun fiyatlı bir alışverişin neydi?'),
  ('If your week were a movie genre, what would it be?', 'Haftan bir film türü olsaydı hangisi olurdu?'),
  ('Tell us a harmless lie you believed for way too long.', 'Çok uzun süre inandığın zararsız bir yalanı anlat.'),
  ('Show us something nearby that matches your mood.', 'Yakınında ruh hâline uyan bir şey göster.'),
  ('What is the most chaotic thing that happened to you this week?', 'Bu hafta başına gelen en kaotik şey neydi?'),
  ('What would you name a boat if you had one?', 'Bir teknen olsaydı adını ne koyardın?'),
  ('Recommend something you love in exactly five words.', 'Sevdiğin bir şeyi tam beş kelimeyle öner.'),
  ('What is your oddly specific pet peeve?', 'Seni sinir eden aşırı spesifik şey ne?'),
  ('Show us a photo from your camera roll that needs context—keep anything private off-screen.', 'Galerinden açıklama gerektiren bir fotoğraf göster; özel şeyleri ekrandan uzak tut.'),
  ('If animals could talk, which one would be the rudest?', 'Hayvanlar konuşabilseydi en kabası hangisi olurdu?'),
  ('What is a smell that instantly brings back a memory?', 'Hangi koku seni anında bir anıya götürüyor?'),
  ('Show us the snack you would choose for a midnight mission.', 'Gece yarısı görevi için seçeceğin atıştırmalığı göster.'),
  ('What is the best bad movie you have ever watched?', 'İzlediğin en iyi kötü film hangisiydi?'),
  ('Give your day a rating out of ten and defend your score.', 'Gününe on üzerinden puan ver ve nedenini savun.'),
  ('What app would you delete from existence for one week?', 'Hangi uygulamayı bir haftalığına dünyadan silerdin?'),
  ('Show us something you made, fixed, or customized.', 'Yaptığın, tamir ettiğin veya kişiselleştirdiğin bir şeyi göster.'),
  ('If you had a personal mascot, what would it be?', 'Kişisel bir maskotun olsaydı ne olurdu?'),
  ('Do your best two-second victory dance.', 'En iyi iki saniyelik zafer dansını yap.'),
  ('Balance on one foot while telling us what you had for breakfast.', 'Kahvaltıda ne yediğini anlatırken tek ayak üzerinde dur.'),
  ('Find and show us something blue before the countdown reaches ten.', 'On saniye dolmadan mavi bir şey bul ve göster.'),
  ('Recreate your favorite emoji using your whole body.', 'Favori emojini tüm vücudunla canlandır.'),
  ('Do five seconds of the worst dancing you can manage.', 'Yapabildiğin en kötü dansı beş saniye boyunca sergile.'),
  ('Walk toward the camera like you are entering a wrestling arena.', 'Güreş arenasına giriyormuş gibi kameraya doğru yürü.'),
  ('Strike a superhero pose and reveal your completely useless superpower.', 'Süper kahraman pozu ver ve tamamen işe yaramaz süper gücünü açıkla.'),
  ('Show us your fastest safe lap around the room.', 'Odanın etrafındaki en hızlı güvenli turunu göster.'),
  ('Do a slow-motion celebration for something small you accomplished today.', 'Bugün başardığın küçük bir şeyi ağır çekimde kutla.'),
  ('Try to touch your toes, then rate your flexibility honestly.', 'Ayak parmaklarına dokunmayı dene, sonra esnekliğine dürüstçe puan ver.'),
  ('Act out your morning routine without saying a word.', 'Sabah rutinini hiç konuşmadan canlandır.'),
  ('Grab the nearest harmless object and use it as a microphone.', 'Yakındaki güvenli bir nesneyi kap ve mikrofon olarak kullan.'),
  ('Do three dance moves and give each one a name.', 'Üç dans hareketi yap ve her birine isim ver.'),
  ('Make the tallest safe tower you can from three nearby objects.', 'Yakındaki üç nesneyle yapabileceğin en yüksek güvenli kuleyi kur.'),
  ('Spin once, strike a pose, and hold it for three seconds.', 'Bir kez dön, poz ver ve üç saniye pozunu koru.'),
  ('Show us your best runway walk in the space you have.', 'Bulunduğun alanda en iyi podyum yürüyüşünü göster.'),
  ('Mime your favorite hobby and let everyone guess what it is.', 'Favori hobini sessizce canlandır; herkes ne olduğunu tahmin etsin.'),
  ('Do your best impression of an animal crossing the room.', 'Odayı geçen bir hayvanı en iyi şekilde taklit et.'),
  ('Find something softer than your sleeve and show us.', 'Kolundan daha yumuşak bir şey bul ve göster.'),
  ('Attempt one safe trick with an everyday object—nothing breakable.', 'Günlük bir nesneyle güvenli bir numara dene; kırılabilir bir şey kullanma.'),
  ('Show us your signature dance move, even if you invent it right now.', 'Şu an uydurman gerekse bile imza dans hareketini göster.'),
  ('Stand like a statue that represents your current mood.', 'Şu anki ruh hâlini anlatan bir heykel gibi dur.'),
  ('Do ten seconds of air guitar to the song in your head.', 'Aklındaki şarkıya on saniye hayali gitar çal.'),
  ('Walk across the room as if the floor has suddenly become jelly.', 'Zemin aniden jöleye dönüşmüş gibi odada yürü.'),
  ('Build a tiny hat from something nearby and model it.', 'Yakındaki bir şeyden minik bir şapka yap ve sergile.'),
  ('Do a five-second stretch and narrate it like a sports commentator.', 'Beş saniyelik esneme yap ve spor spikeri gibi anlat.'),
  ('Race the clock: bring back the weirdest safe object you can find in twenty seconds.', 'Zamana karşı yarış: yirmi saniyede bulabildiğin en garip güvenli nesneyi getir.'),
  ('Act out the last movie or show you watched without using words.', 'İzlediğin son film veya diziyi konuşmadan canlandır.'),
  ('Make a heart shape using your hands, arms, or two nearby objects.', 'Ellerinle, kollarınla veya iki nesneyle kalp şekli yap.'),
  ('Create a handshake with yourself. Yes, somehow.', 'Kendinle bir tokalaşma hareketi yarat. Evet, bir şekilde.'),
  ('Freeze in the exact pose that sums up your day.', 'Gününü özetleyen pozda donup kal.'),
  ('Show us how you would celebrate winning a completely imaginary award.', 'Tamamen hayalî bir ödül kazansaydın nasıl kutlayacağını göster.'),
  ('Take five steps like a robot and introduce yourself in character.', 'Robot gibi beş adım at ve karakterini bozmadan kendini tanıt.'),
  ('Pretend the camera is a mirror and give yourself a tiny pep talk.', 'Kamerayı ayna gibi düşün ve kendine kısa bir moral konuşması yap.'),
  ('Find something that starts with the first letter of your name.', 'Adının ilk harfiyle başlayan bir şey bul.'),
  ('Show us your comfiest sitting position.', 'En rahat oturuş şeklini göster.'),
  ('Without leaving your safe space, point to the most interesting thing you can see.', 'Güvenli alanından ayrılmadan görebildiğin en ilginç şeyi işaret et.'),
  ('Make a sound effect for your current energy level and act it out.', 'Şu anki enerji seviyene bir ses efekti yap ve canlandır.'),
  ('Teach us one simple move, stretch, or gesture we can copy.', 'Bize taklit edebileceğimiz basit bir hareket, esneme veya jest öğret.'),
  ('End your video with the most overdramatic exit possible.', 'Videonu mümkün olan en dramatik çıkışla bitir.')
) AS new_prompts(prompt_text, prompt_tr)
ON CONFLICT (text) DO UPDATE
SET translations = COALESCE(prompts.translations, '{}'::jsonb) || EXCLUDED.translations;
